      "name": "decision",
      "type": "string",
      "required": true,
      "description": "The action Access will take if a user matches this policy. Infrastructure application policies can only use the Allow action."
    },
    {
      "name": "exclude",
      "type": "string",
      "required": false,
      "description": "Rules evaluated with a NOT logical operator. To match the policy, a user cannot meet any of the Exclude rules. Provide as a JSON array of objects or @path/to/file.json."
    },
    {
      "name": "include",
      "type": "string",
      "required": true,
      "description": "Rules evaluated with an OR logical operator. A user needs to meet only one of the Include rules. Provide as a JSON array of objects or @path/to/file.json."
    },
    {
      "name": "name",
      "type": "string",
      "required": true,
      "description": "The name of the Access policy."
    },
    {
      "name": "policy-resolution-account-id",
      "type": "string",
      "required": false,
